    """
    response = render(
        request,
        "will_of_the_prophets/public_board.html",
        {
            "board": board.Board(),
            "special_square_types": models.SpecialSquareType.objects.all(),
        },
    )

    canonical_url = settings.PUBLIC_BOARD_CANONICAL_URL
    if canonical_url:
