To fix this, I have modified `create_success_response` to resolve the stringified return annotation using `typing.get_type_hints`. This ensures that the actual type is used for schema generation, even when annotations are stringized.

```python
def create_success_response(
    route_handler: "HTTPRouteHandler",
    generate_examples: bool,
    plugins: list["OpenAPISchemaPluginProtocol"],
    schemas: dict[str, "Schema"],
) -> OpenAPIResponse:
    """Create the schema for a success response."""
    signature = route_handler.signature
    # Resolve stringified annotations
    from typing import get_type_hints
    try:
        type_hints = get_type_hints(route_handler.handler)
        return_annotation = type_hints.get("return") or signature.return_annotation
    except Exception:
        return_annotation = signature.return_annotation

    default_descriptions: dict[Any, str] = {
        Stream: "Stream Response",
        Redirect: "Redirect Response",
        File: "File Download",
    }
    description = (
        route_handler.response_description
        or default_descriptions.get(return_annotation)
        or HTTPStatus(route_handler.status_code).description
    )

    if return_annotation not in {signature.empty, None, Redirect, File, Stream}:
        if return_annotation is Template:
            return_annotation = str
            route_handler.media_type = get_enum_string_value(MediaType.HTML)
        elif is_class_and_subclass(get_origin(return_annotation), StarliteResponse):
            return_annotation = get_args(return_annotation)[0] or Any

        result = create_schema(
            field=SignatureField.create(field_type=return_annotation),
            generate_examples=generate_examples,
