        tokens = []
        while idx < len(xpath):
            end = self._get_xpath_token_end(idx+1, xpath)
            token = xpath[idx+1:end]
            tokens.append(token)
            idx = end

        return tokens

    def _get_xpath_token_end(self, start, xpath):
        idx = start
        while idx < len(xpath):
            if xpath[idx] == PathAddressing.XPATH_SEPARATOR:
