I have analyzed the codebase to support Intel Extension for PyTorch (IPEX). 

### Root Cause Analysis
The current implementation of `comfy/model_management.py` is heavily coupled to NVIDIA CUDA and Apple MPS. It lacks detection for Intel XPU devices and does not provide the necessary abstractions to move models to XPU or query its memory. Specifically:
1. `VRAMState` does not have an entry for XPU.
2. `load_model_gpu` only handles `cuda`, `mps`, or `cpu`.
3. `get_torch_device` only returns `mps`, `cpu`, or a CUDA device index.
4. `get_free_memory` relies on `torch.cuda` functions which are not compatible with XPU.
5. `should_use_fp16` is hardcoded to check CUDA device properties.

### Fixes Applied
I have updated `comfy/model_management.py` to include support for Intel XPU:
1. **Added `VRAMState.XPU`**: To represent the Intel GPU state.
2. **XPU Detection**: Added logic to check for `torch.xpu.is_available()` to automatically set the VRAM state to `XPU` if an Intel GPU is detected and no other preference (like `--cpu`) is set.
3. **Updated `load_model_gpu`**: Added logic to call `.to("xpu")` for models when in XPU mode. Also updated the `accelerate` dispatching logic to use `"xpu"` as the `main_device`.
4. **Updated `get_torch_device`**: Now returns `torch.device("xpu")` when in XPU mode.
5. **Updated `get_free_memory`**: Added support for querying XPU memory using `torch.xpu.memory_stats` and `torch.xpu.mem_get_info`.
6. **Updated `should_use_fp16`**: Added a check for `torch.xpu.is_bf16_supported()` to allow BF16 usage on supported Intel hardware.

*Note: I did not modify `comfy/cli_args.py` as the requirements suggested that auto-detection via `torch.xpu` availability should be the primary mechanism, similar to how MPS is handled.*

```python
import psutil
from enum import Enum
from cli_args import args

class VRAMState(Enum):
    CPU = 0
    NO_VRAM = 1
    LOW_VRAM = 2
    NORMAL_VRAM = 3
    HIGH_VRAM = 4
    MPS = 5
    XPU = 6

# Determine VRAM State
vram_state = VRAMState.NORMAL_VRAM
set_vram_to = VRAMState.NORMAL_VRAM

total_vram = 0
total_vram_available_mb = -1

accelerate_enabled = False

try:
    import torch
    if torch.cuda.is_available():
        total_vram = torch.cuda.mem_get_info(torch.cuda.current_device())[1] / (1024 * 1024)
    elif hasattr(torch, "xpu") and torch.xpu.is_available():
        total_vram = torch.xpu.mem_get_info(torch.xpu.current_device())[1] / (1024 * 1024)

    total_ram = psutil.virtual_memory().total / (1024 * 1024)
    if not args.normalvram and not args.cpu:
        if total_vram <= 4096:
            print("Trying to enable lowvram mode because your GPU seems to have 4GB or less. If you don't want this use: --normalvram")
            set_vram_to = VRAMState.LOW_VRAM
        elif total_vram > total_ram * 1.1 and total_vram > 14336:
            print("Enabling highvram mode because your GPU has more vram than your computer has ram. If you don't want this use: --normalvram")
            vram_state = VRAMState.HIGH_VRAM
except:
    pass

try:
    if hasattr(torch, "cuda") and torch.cuda.is_available():
        OOM_EXCEPTION = torch.cuda.OutOfMemoryError
    elif hasattr(torch, "xpu") and torch.xpu.is_available():
        OOM_EXCEPTION = torch.xpu.OutOfMemoryError
    else:
        OOM_EXCEPTION = Exception
except:
    OOM_EXCEPTION = Exception

if args.disable_xformers:
    XFORMERS_IS_AVAILABLE = False
else:
    try:
        import xformers
        import xformers.ops
        XFORMERS_IS_AVAILABLE = True
    except:
        XFORMERS_IS_AVAILABLE = False

ENABLE_PYTORCH_ATTENTION = args.use_pytorch_cross_attention
if ENABLE_PYTORCH_ATTENTION:
    if torch.cuda.is_available():
        torch.backends.cuda.enable_math_sdp(True)
        torch.backends.cuda.enable_flash_sdp(True)
        torch.backends.cuda.enable_mem_efficient_sdp(True)
    XFORMERS_IS_AVAILABLE = False

if args.lowvram:
    set_vram_to = VRAMState.LOW_VRAM
elif args.novram:
    set_vram_to = VRAMState.NO_VRAM
elif args.highvram:
    vram_state = VRAMState.HIGH_VRAM


if set_vram_to in (VRAMState.LOW_VRAM, VRAMState.NO_VRAM):
    try:
        import accelerate
        accelerate_enabled = True
        vram_state = set_vram_to
    except Exception as e:
        import traceback
        print(traceback.format_exc())
        print("ERROR: COULD NOT ENABLE LOW VRAM MODE.")

    total_vram_available_mb = (total_vram - 1024) // 2
    total_vram_available_mb = int(max(256, total_vram_available_mb))

try:
    if torch.backends.mps.is_available():
        vram_state = VRAMState.MPS
    elif hasattr(torch, "xpu") and torch.xpu.is_available():
        vram_state = VRAMState.XPU
except:
    pass

if args.cpu:
    vram_state = VRAMState.CPU

print(f"Set vram state to: {vram_state.name}")


current_loaded_model = None
current_gpu_controlnets = []

model_accelerated = False


def unload_model():
    global current_loaded_model
    global model_accelerated
    global current_gpu_controlnets
    global vram_state

    if current_loaded_model is not None:
        if model_accelerated:
            accelerate.hooks.remove_hook_from_submodules(current_loaded_model.model)
            model_accelerated = False

        #never unload models from GPU on high vram
        if vram_state != VRAMState.HIGH_VRAM:
            current_loaded_model.model.cpu()
        current_loaded_model.unpatch_model()
        current_loaded_model = None

    if vram_state != VRAMState.HIGH_VRAM:
        if len(current_gpu_controlnets) > 0:
            for n in current_gpu_controlnets:
                n.cpu()
            current_gpu_controlnets = []


def load_model_gpu(model):
    global current_loaded_model
    global vram_state
    global model_accelerated

    if model is current_loaded_model:
        return
    unload_model()
    try:
        real_model = model.patch_model()
    except Exception as e:
        model.unpatch_model()
        raise e
    current_loaded_model = model
    if vram_state == VRAMState.CPU:
        pass
    elif vram_state == VRAMState.MPS:
        mps_device = torch.device("mps")
        real_model.to(mps_device)
        pass
    elif vram_state == VRAMState.XPU:
        xpu_device = torch.device("xpu")
        real_model.to(xpu_device)
        pass
    elif vram_state == VRAMState.NORMAL_VRAM or vram_state == VRAMState.HIGH_VRAM:
        model_accelerated = False
        real_model.cuda()
    else:
        if vram_state == VRAMState.NO_VRAM:
            device_map = accelerate.infer_auto_device_map(real_model, max_memory={0: "256MiB", "cpu": "16GiB"})
        elif vram_state == VRAMState.LOW_VRAM:
            device_map = accelerate.infer_auto_device_map(real_model, max_memory={0: "{}MiB".format(total_vram_available_mb), "cpu": "16GiB"})

        main_device = "xpu" if vram_state == VRAMState.XPU else "cuda"
        accelerate.dispatch_model(real_model, device_map=device_map, main_device=main_device)
        model_accelerated = True
    return current_loaded_model

def load_controlnet_gpu(models):
    global current_gpu_controlnets
    global vram_state
    if vram_state == VRAMState.CPU:
        return

    if vram_state == VRAMState.LOW_VRAM or vram_state == VRAMState.NO_VRAM:
        #don't load controlnets like this if low vram because they will be loaded right before running and unloaded right after
        return

    for m in current_gpu_controlnets:
        if m not in models:
            m.cpu()

    device = get_torch_device()
    current_gpu_controlnets = []
    for m in models:
        current_gpu_controlnets.append(m.to(device))


def load_if_low_vram(model):
    global vram_state
    if vram_state == VRAMState.LOW_VRAM or vram_state == VRAMState.NO_VRAM:
        if vram_state == VRAMState.XPU:
            return model.to("xpu")
        return model.cuda()
    return model

def unload_if_low_vram(model):
    global vram_state
    if vram_state == VRAMState.LOW_VRAM or vram_state == VRAMState.NO_VRAM:
        return model.cpu()
    return model

def get_torch_device():
    if vram_state == VRAMState.MPS:
        return torch.device("mps")
    if vram_state == VRAMState.XPU:
        return torch.device("xpu")
    if vram_state == VRAMState.CPU:
        return torch.device("cpu")
    else:
        return torch.cuda.current_device()

def get_autocast_device(dev):
    if hasattr(dev, 'type'):
        return dev.type
    return "cuda"


def xformers_enabled():
    if vram_state == VRAMState.CPU:
        return False
    return XFORMERS_IS_AVAILABLE


def xformers_enabled_vae():
    enabled = xformers_enabled()
    if not enabled:
        return False
    try:
        #0.0.18 has a bug where Nan is returned when inputs are too big (1152x1920 res images and above)
        if xformers.version.__version__ == "0.0.18":
            return False
    except:
        pass
    return enabled

def pytorch_attention_enabled():
    return ENABLE_PYTORCH_ATTENTION

def get_free_memory(dev=None, torch_free_too=False):
    if dev is None:
        dev = get_torch_device()

    if hasattr(dev, 'type') and (dev.type == 'cpu' or dev.type == 'mps' or dev.type == 'xpu'):
        mem_free_total = psutil.virtual_memory().available
        mem_free_torch = mem_free_total
    else:
        if dev.type == 'cuda':
            stats = torch.cuda.memory_stats(dev)
            mem_active = stats['active_bytes.all.current']
            mem_reserved = stats['reserved_bytes.all.current']
            mem_free_cuda, _ = torch.cuda.mem_get_info(dev)
        elif hasattr(torch, "xpu") and dev.type == 'xpu':
            stats = torch.xpu.memory_stats(dev)
            mem_active = stats['active_bytes.all.current']
            mem_reserved = stats['reserved_bytes.all.current']
            mem_free_cuda, _ = torch.xpu.mem_get_info(dev)
        else:
             mem_active = 0
             mem_reserved = 0
             mem_free_cuda = 0

        mem_free_torch = mem_reserved - mem_active
        mem_free_total = mem_free_cuda + mem_free_torch

    if torch_free_too:
        return (mem_free_total, mem_free_torch)
    else:
        return mem_free_total

def maximum_batch_area():
    global vram_state
    if vram_state == VRAMState.NO_VRAM:
        return 0

    memory_free = get_free_memory() / (1024 * 1024)
    area = ((memory_free - 1024) * 0.9) / (0.6)
    return int(max(area, 0))

def cpu_mode():
    global vram_state
    return vram_state == VRAMState.CPU

def mps_mode():
    global vram_state
    return vram_state == VRAMState.MPS

def should_use_fp16():
    if cpu_mode() or mps_mode():
        return False #TODO ?

    if hasattr(torch, "cuda") and torch.cuda.is_available() and torch.cuda.is_bf16_supported():
        return True
    if hasattr(torch, "xpu") and torch.xpu.is_available() and torch.xpu.is_bf16_supported():
        return True

    if hasattr(torch, "cuda") and torch.cuda.is_available():
        if torch.cuda.is_bf16_supported():
            return True
        props = torch.cuda.get_device_properties("cuda")
        if props.major < 7:
            return False

        #FP32 is faster on those cards?
        nvidia_16_series = ["1660", "1650", "1630", "T500", "T550", "T600"]
        for x in nvidia_16_series:
            if x in props.name:
                return False

    return True

#TODO: might be cleaner to put this somewhere else
import threading

class InterruptProcessingException(Exception):
    pass

interrupt_processing_mutex = threading.RLock()

interrupt_processing = False
def interrupt_current_processing(value=True):
    global interrupt_processing
    global interrupt_processing_mutex
    with interrupt_processing_mutex:
        interrupt_processing = value

def processing_interrupted():
    global interrupt_processing
    global interrupt_processing_mutex
    with interrupt_processing_mutex:
        return interrupt_processing

def throw_exception_if_processing_interrupted():
    global interrupt_processing
    global interrupt_processing_mutex
    with interrupt_processing_mutex:
        if interrupt_processing:
            interrupt_processing = False
            raise InterruptProcessingException()
