        raise NotImplementedError

    def update_config(self, config):
        """Updates the config for all loggers."""

        pass

    def close(self):
        """Releases all resources used by this logger."""

        pass

    def flush(self):
        """Flushes all disk writes to storage."""

        pass


class NoopLogger(Logger):
