            self._csv_out = csv.DictWriter(self._file, flattened_result.keys())
            if not self._continuing:
                self._csv_out.writeheader()
        self._csv_out.writerow(
            {k: v
             for k, v in flattened_result.items() if k in self._csv_out.fieldnames})

    def flush(self):
